entries[228117] = { ["name"] = "Plans: Refined Arcanite Champion", ["text"] = "Requires Blacksmithing (300)\nRequiresMaster Swordsmith\nUse: Teaches you how to make an Arcanite Champion.\nRefined Arcanite Champion\nBinds when equipped\nTwo-Hand Sword\n107 - 161 Damage Speed 2.00\n(67.00 damage per second)\nDurability 100 / 100\nRequires Level 60\nChance on hit: Heal self for 270 to 450 and Increases Strength by 120 for 30 sec.\nChance on hit: Increases damage done by 20 and attack speed by 5% for 15 sec.\nRequires Arcanite Champion , Elemental Sharpening Stone (10)" }
